      stateEnteredTurn: world.step,
      lastPlayerX: apos.x,
      lastPlayerY: apos.y,
      commandCooldown: 0,
      rangedCooldown: 0,
    });
  } catch {}

  world.emit('spell:summon_skeleton', {
    actor,
    skeletonId,
    faction: summonFaction,
    at: { x: spawnTile.x, y: spawnTile.y },
  });
};

