      const settle = 0.985 + 0.015 * Math.sin(fxTime * 1.25 + h.phase);
      const flicker = Math.max(0.10, Math.min(1.52, heat * settle));
      out.push({
        x: h.x,
        y: h.y,
        radius: h.radius * (0.84 + plateau * 0.34),
        color: h.color,
        flicker,
      });
