      const life = f.max > 0 ? Math.max(0, Math.min(1, f.ttl / f.max)) : 0;
      if (life <= 0) continue;
      out.push({
        x: f.x,
        y: f.y,
        radius: f.radius * (0.66 + life * 0.44),
        color: [255, 142, 58],
