    }
    for (let i = 0; i < _blastwaveFx.length; i++) {
      const b = _blastwaveFx[i];
      out.push({ x: b.x, y: b.y, radius: (b.radius || 2) * 2 * b.alpha, color: [255, 200, 100] });
    }
    for (let i = 0; i < _frostNovaFx.length; i++) {
