export function isEntityOnCurrentFloor(world, entityId, opts = {}) {
  const id = Number(entityId || 0) | 0;
  if (!(id > 0) || !world.isAlive(id)) return false;
  if (opts.treatPlayerAsOnFloor && world.has(id, Player)) return true;
