  const id = Number(entityId || 0) | 0;
  if (!(id > 0)) return false;
  for (const [, ds] of world.query(DungeonState)) {
    if (!Array.isArray(ds?.floorEntityIds)) return false;
    if (!ds.floorEntityIds.includes(id)) ds.floorEntityIds.push(id);
    return true;
  }
